import math

def check_expression(n):
    if n < 0:
        return None
    denominator = 2 * n - 1
    if denominator == 0:
        return "Undefined"

    numerator = 3 * (math.factorial(n + 2) + 1)

    if numerator % denominator == 0:
        return numerator // denominator
    else:
        return "Not Integer"

# Test initial values as requested in the task exploration
test_values = [0, 1, 2, 3, 4, 5, 6]
results = {}
for n in test_values:
    results[n] = check_expression(n)

print(results)
